'use strict';
let characteristics=null,stockManifest=null,stockRows=[],stockFiltered=[],stockPage=0,stockSort=0,stockDirection=1,stockToken=0;
const stockCache=new Map();
const processDigits=v=>formatProcess(v).replace(/\D/g,'');
function substances(v){return String(v||'Sem registro').split(/\s*\/\s*|\s*;\s*/).map(s=>s.trim()).filter(Boolean)}
function matchesExtra(r){const q=$('process-filter').value.trim(),sub=$('substance-filter').value;return (!q||(processDigits(q)&&processDigits(r.p).includes(processDigits(q))))&&(!sub||substances(r.sub).includes(sub))}
['process-filter','substance-filter'].forEach(id=>$(id).addEventListener(id==='process-filter'?'input':'change',()=>{page=0;render()}));
const renderBeforeInsights=render;render=function(){renderBeforeInsights();if(!data)return;const rd=$('round').value;if(['6','7'].includes(rd)){$('total').textContent='Não se aplica';$('rate').textContent='Não se aplica';$('median').textContent='Não se aplica';$('nwin').textContent=rd==='6'?'Avaliação social':'Edital cancelado'}const statuses=[...new Set(filtered.map(r=>r.s))];$('outcomes').innerHTML=statuses.map(s=>bar(s,filtered.filter(r=>r.s===s).length,filtered.length,colors[s]||'#71647c')).join('')||'<p>Nenhuma área na seleção.</p>'};
async function getCharacteristics(){if(!characteristics){const r=await fetch('characteristics.json');if(!r.ok)throw Error('Características indisponíveis');characteristics=await r.json()}return characteristics}
async function enrichDetail(r){try{const chars=r.stock||((await getCharacteristics())[r.p]);if(!$('detail').open||!$('detailbody').querySelector('h2')?.textContent.includes(formatProcess(r.p)))return;const box=document.createElement('section');box.className='current-characteristics';box.innerHTML='<h3>Características no cadastro atual</h3>'+(chars?'<div class="detail-grid">'+[[5,'Uso da substância'],[6,'Regime de disponibilidade'],[7,'Indicação de interesse (nominação)'],[8,'Fase do processo'],[9,'Situação do processo'],[10,'Situação no estoque'],[11,'Incluído em edital'],[12,'Última situação em edital']].map(([i,name])=>`<div class="detail-item"><span>${name}</span><b>${esc(chars[i]||'Sem registro')}</b></div>`).join('')+'</div>':'<p>Não foi encontrado vínculo com o arquivo de estoque atual.</p>')+'<p class="caption">Essas características são do retrato atual e podem ter mudado desde a rodada. Para entender a entrada em disponibilidade, examine os eventos e o ato administrativo correspondente; o estoque não fornece uma causa única confirmada.</p>';const target=$('detailbody').querySelector('h3');target.before(box)}catch(e){console.error(e)}}
async function refreshInsights(){if(!overviewData)return;const previous=$('substance-filter').value;const ss=[...new Set(overviewData.rows.flatMap(r=>substances(r.sub)))].sort((a,b)=>a.localeCompare(b,'pt-BR'));$('substance-filter').innerHTML='<option value="">Todas as substâncias</option>'+ss.map(s=>`<option>${esc(s)}</option>`).join('');$('substance-filter').value=ss.includes(previous)?previous:'';const states=[...new Set(overviewData.rows.map(r=>r.u))].sort();$('profile-state').innerHTML='<option value="">Todos os estados</option>'+states.map(s=>`<option>${esc(s)}</option>`).join('');renderProfiles();renderTerritory()}
async function renderProfiles(){if(!overviewData)return;let ch={};try{ch=await getCharacteristics()}catch(e){}const rd=$('profile-round').value,uf=$('profile-state').value,rows=overviewData.rows.filter(r=>(!rd||r.r==rd)&&(!uf||r.u===uf));const outcomes=[...new Set(rows.map(r=>r.s))].sort((a,b)=>(['Arrematada','Conquistada','Livre'].indexOf(a)+1||99)-(['Arrematada','Conquistada','Livre'].indexOf(b)+1||99));const counts=values=>{const m=new Map();values.forEach(v=>m.set(v,(m.get(v)||0)+1));return [...m].sort((a,b)=>b[1]-a[1])};const top=values=>counts(values).slice(0,3).map(([s,n])=>esc(s)+' ('+num(n)+')').join('<br>')||'Sem registro';$('profile-note').textContent=num(rows.length)+' áreas por rodada; '+num(rows.filter(r=>ch[r.p]).length)+' com características ligadas ao estoque atual. Substâncias, uso, nominação e regime são do cadastro atual. As rodadas 6 e 7 têm situações próprias e ficam fora das comparações financeiras.';$('profile-table').innerHTML='<table><thead><tr><th>Resultado</th><th>Áreas</th><th>Área mediana (ha)</th><th>Lance mediano positivo</th><th>Estados mais frequentes</th><th>Regimes mais frequentes</th><th>Usos mais frequentes</th></tr></thead><tbody>'+outcomes.map(s=>{const a=rows.filter(r=>r.s===s),areas=a.map(r=>Number(r.ha)).filter(v=>Number.isFinite(v)&&v>0);return `<tr><td>${esc(s)}</td><td>${num(a.length)}</td><td>${areas.length?dec(median(areas)):'Sem registro'}</td><td>${s==='Arrematada'?money(median(a.filter(r=>r.v>0).map(r=>r.v))):'Não se aplica'}</td><td>${top(a.map(r=>r.u))}</td><td>${top(a.map(r=>ch[r.p]?.[6]||r.reg||'Sem registro'))}</td><td>${top(a.map(r=>ch[r.p]?.[5]||'Sem registro'))}</td></tr>`}).join('')+'</tbody></table>';$('profile-substances').innerHTML=outcomes.map(s=>{const a=rows.filter(r=>r.s===s);return '<h3>'+esc(s)+'</h3>'+counts(a.flatMap(r=>[...new Set(substances(r.sub))])).slice(0,5).map(([sub,n])=>bar(sub,n,a.length,colors[s]||'#074987',num(n)+' · '+pct(n/a.length))).join('')}).join('')+'<p class="caption">Uma área pode ter várias substâncias; as participações não precisam somar 100%.</p>';$('free-history').innerHTML=[8,7,6,5,4,3,2,1].filter(n=>!rd||n==rd).map(n=>{const a=overviewData.rows.filter(r=>r.r===n&&(!uf||r.u===uf)),free=a.filter(r=>r.s==='Livre').length;return n===7?'<p><b>7ª rodada:</b> cancelada; indicador não se aplica.</p>':bar(n+'ª'+(n===6?' · social':''),free,a.length,'#607d8b',num(free)+' / '+num(a.length)+' · '+(a.length?pct(free/a.length):'—'))}).join('')}
['profile-round','profile-state'].forEach(id=>$(id).onchange=renderProfiles);
async function renderTerritory(){if(!overviewData)return;const grouped=new Map();overviewData.rows.forEach(r=>{if(r.v>0)grouped.set(r.u,(grouped.get(r.u)||0)+r.v)});const ranked=[...grouped].sort((a,b)=>b[1]-a[1]),max=ranked[0]?.[1]||1;const select=uf=>{openSelection();$('state').value=uf;render()};$('state-ranking').innerHTML=ranked.slice(0,10).map(([uf,total])=>`<button class="state-row" data-uf="${esc(uf)}">${bar(uf,total,max,'#1351b4',shortMoney(total))}</button>`).join('');$('state-ranking').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.uf));try{const r=await fetch('brasil.json');const geo=await r.json();$('overview-map').innerHTML=geo.features.map(f=>{const uf=f.properties.name||f.properties.sigla||f.properties.SIGLA_UF||f.properties.abbrev||f.properties.UF||f.properties.name;const value=grouped.get(uf)||0,polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return `<path tabindex="0" role="button" aria-label="${esc(uf)}: ${money(value)}" data-uf="${esc(uf)}" fill="${value?'#1351b4':'#e6eaf0'}" fill-opacity="${value?.2+.8*Math.sqrt(value/max):1}" stroke="#fff" stroke-width="1" d="${polys.map(poly=>poly.map(ring=>ring.map((p,i)=>(i?'L':'M')+project(p).join(',')).join('')+'Z').join('')).join('')}"><title>${esc(uf)} · ${money(value)}</title></path>`}).join('');$('overview-map').querySelectorAll('path').forEach(el=>{el.onclick=()=>select(el.dataset.uf);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(el.dataset.uf)}}})}catch(e){$('overview-map').innerHTML='<text x="20" y="40">Mapa indisponível. Use os estados ao lado.</text>'}}
async function loadStock(){const token=++stockToken;$('stock-message').textContent='Carregando estoque completo…';try{if(!stockManifest){const r=await fetch('stock/index.json');if(!r.ok)throw Error('manifest');stockManifest=await r.json();$('stock-kpis').innerHTML=Object.entries(stockManifest.status).map(([s,n])=>`<article><span>${esc(s)}</span><strong>${num(n)}</strong></article>`).join('');$('stock-state').innerHTML='<option value="">Todos os estados</option>'+stockManifest.states.map(s=>`<option>${esc(s.uf)}</option>`).join('');$('stock-status').innerHTML='<option value="">Todas as situações</option>'+Object.keys(stockManifest.status).map(s=>`<option>${esc(s)}</option>`).join('')}const uf=$('stock-state').value,parts=stockManifest.states.filter(s=>!uf||s.uf===uf);const loaded=await Promise.all(parts.map(async s=>{if(!stockCache.has(s.file)){const r=await fetch('stock/'+s.file);if(!r.ok)throw Error(s.file);stockCache.set(s.file,await r.json())}return stockCache.get(s.file)}));if(token!==stockToken)return;stockRows=loaded.flat();stockPage=0;$('stock-message').textContent=num(stockManifest.total)+' processos no estoque completo · extração '+String(stockManifest.extracted_at).slice(0,10).split('-').reverse().join('/')+'. Abra a ficha para ver os eventos e a poligonal.';renderStock()}catch(e){if(token===stockToken)$('stock-message').textContent='Não foi possível carregar o estoque. Abra esta seção novamente para tentar.'}}
function renderStock(){const q=fold($('stock-search').value.trim()),digits=q.replace(/\D/g,''),s=$('stock-status').value;stockFiltered=stockRows.filter(r=>(!s||r[10]===s)&&(!q||fold([r[0],r[2],r[4]].join(' ')).includes(q)||(/^[\d.\/]+$/.test(q)&&r[0].replace(/\D/g,'').includes(digits))));stockFiltered.sort((a,b)=>stockDirection*(stockSort===3?Number(a[3].replace(',','.'))-Number(b[3].replace(',','.')):a[stockSort].localeCompare(b[stockSort],'pt-BR',{numeric:true})));stockPage=Math.min(stockPage,Math.max(0,Math.ceil(stockFiltered.length/25)-1));const offset=stockPage*25;$('stock-table').innerHTML='<table><thead><tr>'+[[0,'Processo'],[2,'Município / UF'],[4,'Substância'],[3,'Área (ha)'],[10,'Situação no estoque']].map(([i,s])=>`<th><button data-stock-sort="${i}">${s} ↕</button></th>`).join('')+'<th>Ficha</th></tr></thead><tbody>'+stockFiltered.slice(offset,offset+25).map((r,i)=>`<tr><td>${esc(formatProcess(r[0]))}</td><td>${esc(r[2])}<small>${esc(r[1])}</small></td><td>${esc(r[4]||'Sem registro')}</td><td>${esc(r[3])}</td><td>${esc(r[10])}</td><td><button class="link-button" data-stock-index="${offset+i}">Abrir ↗</button></td></tr>`).join('')+'</tbody></table>';$('stock-count').textContent=num(stockFiltered.length)+' processos · página '+(stockPage+1);$('stock-prev').disabled=stockPage===0;$('stock-next').disabled=offset+25>=stockFiltered.length;$('stock-table').querySelectorAll('[data-stock-sort]').forEach(b=>b.onclick=()=>{const key=+b.dataset.stockSort;stockDirection=stockSort===key?-stockDirection:1;stockSort=key;renderStock()});$('stock-table').querySelectorAll('[data-stock-index]').forEach(b=>b.onclick=()=>{const r=stockFiltered[+b.dataset.stockIndex];detail(-1,{p:r[0],u:r[1],m:r[2],ha:Number(r[3].replace(',','.')),sub:r[4],reg:r[6],s:r[10],r:null,a:'',v:null,cf:null,di:null,stock:r})})}
$('stock-state').onchange=loadStock;$('stock-status').onchange=()=>{stockPage=0;renderStock()};$('stock-search').oninput=()=>{stockPage=0;renderStock()};$('stock-prev').onclick=()=>{stockPage--;renderStock()};$('stock-next').onclick=()=>{stockPage++;renderStock()};document.querySelector('[data-view="stock"]').addEventListener('click',loadStock);document.querySelector('[data-view="profiles"]').addEventListener('click',renderProfiles);
// Put the financial indicators first without changing their filter behavior.
const exploreKpis=$('explore').querySelector('.kpis');exploreKpis.prepend($('total').closest('article'));exploreKpis.insertBefore($('median').closest('article'),exploreKpis.children[1]);
